    }
  }
}
machine SwapNames {     // each renames into the other's name
  start state Init { entry { new Scenario((a = Op2(0, 1, 1, 2), b = Op2(0, 2, 1, 1))); } }
}
machine TakeFreed {     // u1 may grab the name u0 just vacated
