}
machine SameName {
  start state Init { entry { new Scenario((a = Op1(0, 1), b = Op1(0, 1))); } }
}
machine RenameChain {   // both rename to the same free name
  start state Init { entry { new Scenario((a = Op2(0, 1, 1, 3), b = Op2(0, 2, 1, 3))); } }
}

